import sympy

# Closed form: a_n = 6^n + 2^n + 3^n - 1

def calculate_an(n):
    return 6**n + 2**n + 3**n - 1

def prime_factorization(n):
    return sympy.factorint(n)

n_values = [6, 7, 8]
results = {}

for n in n_values:
    an = calculate_an(n)
    factors = prime_factorization(an)
    results[n] = (an, factors)

print("Calculations:")
for n, (val, factors) in results.items():
    print(f"a_{n} = {val}")
    print(f"Prime factorization of a_{n}: {factors}")

